<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,shallowRef} from 'vue';
import {unifiedMerge} from '../services';
import {MergeConfirmation} from '../../shared/protocol/merge-import';
import type {Input,Output} from '../../shared/protocol/registry';
const props=defineProps<{inert?:boolean}>(),emit=defineEmits<{busy:[value:boolean];imported:[]}>();
const supported=ref(false),busy=ref(false),unknown=ref(false),error=ref(''),notice=ref(''),accepted=ref(false),force=ref(false);
const source=shallowRef<Output<'storage.merge.open'>>(null),rows=ref<Output<'storage.merge.decks'>['items']>([]),cursor=ref<string|null>(null),selection=ref<string[]>([]),plan=shallowRef<Output<'storage.merge.preview'>>(),pending=shallowRef<Input<'storage.merge.confirm'>|null>(null);
const operationId=ref(localStorage.getItem('gank-merge-operation')??'');let disposed=false;
const selected=computed(()=>rows.value.filter(r=>selection.value.includes(r.sourceDeckId)));
const counts=computed(()=>selected.value.reduce((c,r)=>({cards:c.cards+r.cards.active,recycled:c.recycled+r.cards.recycled,knowledge:c.knowledge+r.knowledge.active+r.knowledge.recycled,history:c.history+r.reviewEvents,drafts:c.drafts+r.drafts+r.unpublishedDrafts}),{cards:0,recycled:0,knowledge:0,history:0,drafts:0}));
function working(value:boolean){busy.value=value;emit('busy',value||unknown.value);}
function invalidate(){plan.value=undefined;accepted.value=false;}
async function load(more=false){if(!source.value)return;const r=await unifiedMerge.decks({scanId:source.value.scanId,limit:50,cursor:more?cursor.value:null});rows.value=more?[...rows.value,...r.items]:r.items;cursor.value=r.nextCursor;}
async function more(){working(true);try{await load(true);}catch(e){error.value=String(e);}finally{working(false);}}
async function choose(){if(busy.value||unknown.value||props.inert)return;working(true);error.value='';notice.value='';source.value=null;rows.value=[];selection.value=[];force.value=false;invalidate();try{source.value=await unifiedMerge.open();if(source.value)await load();else notice.value='已取消选择数据库，当前数据未改变';}catch(e){error.value=String(e);}finally{working(false);}}
async function preview(){if(!source.value||busy.value||unknown.value||props.inert)return;working(true);error.value='';invalidate();try{plan.value=await unifiedMerge.preview({scanId:source.value.scanId,selectedDeckIds:selection.value,forceIndependent:force.value,folderId:null});}catch(e){error.value=String(e);}finally{working(false);}}
async function cancel(){if(busy.value||unknown.value)return false;working(true);try{if(source.value)await unifiedMerge.cancel(source.value.scanId);source.value=null;rows.value=[];selection.value=[];invalidate();notice.value='已取消合并导入，当前数据未改变';return true;}catch(e){error.value=String(e);return false;}finally{working(false);}}
async function commit(c:Input<'storage.merge.confirm'>){if(busy.value||props.inert)return;working(true);error.value='';let reload=false;
 try{const r=await unifiedMerge.confirm(c);pending.value=null;unknown.value=false;source.value=null;invalidate();notice.value=`已独立导入 ${r.imported.length} 个卡片集`+(r.reopened?'':'，请重启后核对结果');reload=r.reopened;}
 catch(e){unknown.value=(e as {outcome?:string}).outcome==='unknown';if(!unknown.value){pending.value=null;localStorage.removeItem('gank-merge-pending');}error.value=String(e);}
 finally{working(false);}if(reload)emit('imported');}
async function confirm(){if(!accepted.value||!plan.value?.confirmation||busy.value||unknown.value)return;pending.value=plan.value.confirmation;operationId.value=pending.value.operationId;await commit(pending.value);}
async function status(){if(!operationId.value||busy.value)return;working(true);error.value='';let reload=false;try{const r=await unifiedMerge.status(operationId.value);notice.value=!r?'尚未找到操作回执，请保留原请求并重启核对':r.state==='committed'?`上次已独立导入 ${r.result?.imported.length??0} 个卡片集`+(r.reopened?'':'，请重启核对'):r.state==='aborted'?'上次导入未提交，原数据已保留':'上次导入仍待恢复核对';if(r?.state==='committed'||r?.state==='aborted'){reload=unknown.value&&r.state==='committed'&&r.reopened;unknown.value=false;pending.value=null;source.value=null;invalidate();localStorage.removeItem('gank-merge-pending');}}catch(e){error.value=String(e);}finally{working(false);}if(reload)emit('imported');}
function beforeUnload(e:BeforeUnloadEvent){if(busy.value||unknown.value){e.preventDefault();e.returnValue='';}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{const raw=localStorage.getItem('gank-merge-pending');if(raw){pending.value=MergeConfirmation.parse(JSON.parse(raw));unknown.value=true;emit('busy',true);}supported.value=await unifiedMerge.supported();}catch(e){if(!disposed)error.value=String(e);}});
onBeforeUnmount(()=>{disposed=true;window.removeEventListener('beforeunload',beforeUnload);if(source.value&&!busy.value&&!unknown.value)void unifiedMerge.cancel(source.value.scanId).catch(()=>{});});
defineExpose({close:async()=>!busy.value&&!unknown.value&&(!source.value||await cancel())});
</script>
<template><section class="merge-import" aria-label="合并导入数据库"><h3>合并导入</h3><p>将另一份 Schema606 数据库中的卡片集作为独立副本加入当前库。已有卡片、历史和图片不会被覆盖；同 ID 会重新分配并重映射内部引用。</p><p>来源历史与 FSRS 排期随独立副本保留；当前卡片的历史和排期保持原样。</p>
 <button :disabled="busy||unknown||inert||!supported" @click="choose">选择合并导入数据库</button><p v-if="!supported">当前入口尚未启用数据库合并导入。</p><p v-if="busy" role="status">正在校验来源、媒体与恢复点，请等待结果…</p><p v-if="unknown" role="alert">导入结果未知，请先查询回执或核对原请求，勿再次创建导入。</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <article v-if="source" aria-label="合并导入预览"><p>来源格式：Schema{{source.schemaVersion}} · {{source.deckCount}} 个卡片集 · 全库图片 {{source.media.files}} 个（{{(source.media.bytes/1024/1024).toFixed(2)}} MiB）</p><p>来源待核对操作：{{source.pendingOperations}}；图片按所选内容的实际引用复制。</p>
 <fieldset :disabled="busy||unknown||inert"><legend>选择独立导入的卡片集</legend><label v-for="row in rows" :key="row.sourceDeckId"><input type="checkbox" :value="row.sourceDeckId" v-model="selection" :aria-label="'导入卡片集 '+row.name" @change="invalidate"/>{{row.name}}{{row.recycled?'（回收站）':''}} · 卡片 {{row.cards.active}} / 回收 {{row.cards.recycled}} · 知识点 {{row.knowledge.active+row.knowledge.recycled}} · 历史 {{row.reviewEvents}}</label><button v-if="cursor" @click="more">更多来源卡片集</button><p>已选 {{selected.length}} 个卡片集；卡片 {{counts.cards}} / 回收 {{counts.recycled}}，知识点 {{counts.knowledge}}，草稿 {{counts.drafts}}，学习历史 {{counts.history}}。</p><label><input type="checkbox" v-model="force" @change="invalidate"/>已导入来源也再导一份独立副本（默认跳过相同来源版本）</label><button :disabled="!selection.length" @click="preview">预览合并导入影响</button>
 <template v-if="plan"><p v-if="!plan.selection.closed" role="alert">所选内容存在跨集关联，请补选以下卡片集后重新预览：{{plan.selection.requiredDecks.map(d=>d.name).join('、')}}</p><p v-if="plan.duplicates">本次将新增 {{plan.duplicates.importDeckIds.length}} 个独立卡片集；重复跳过 {{plan.duplicates.skippedDeckIds.length}} 个；依赖阻断 {{plan.duplicates.blockedDeckIds.length}} 个。</p><p v-if="plan.impact">实际新增：卡片集 {{plan.impact.decks}} · 卡片 {{plan.impact.cards}} · 知识点 {{plan.impact.knowledge}} · 草稿 {{plan.impact.drafts}} · 历史 {{plan.impact.reviewEvents}} · 排期 {{plan.impact.schedules}} · 图片 {{plan.impact.mediaFiles}} 个 / {{plan.impact.mediaBytes}} 字节。</p><template v-if="plan.confirmation"><label><input type="checkbox" v-model="accepted"/>我已核对影响，同意新增独立副本并保留当前全部数据</label><button :disabled="!accepted" @click="confirm">确认合并导入</button></template></template><button @click="cancel">取消合并导入</button></fieldset>
 </article><button v-if="operationId" :disabled="busy||inert" @click="status">查询上次导入结果</button><button v-if="unknown&&pending" :disabled="busy||inert" @click="commit(pending)">核对原导入请求</button>
</section></template>
<style scoped>.merge-import{margin-top:24px;border-top:1px solid var(--border);padding-top:20px;min-width:0}p{line-height:1.7;overflow-wrap:anywhere}article,fieldset{min-width:0;margin-top:14px;border:1px solid var(--border);border-radius:10px;padding:16px}label{display:block;margin:12px 0}input[type=checkbox]{display:inline-block;width:auto;margin-right:8px}button{margin:4px;max-width:100%;white-space:normal}</style>
